package com.nexus.property.admin;import com.nexus.property.auth.*;import com.nexus.property.core.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController{private final Db db;public AdminController(Db db){this.db=db;}@GetMapping("/metrics")public Map<String,Object>metrics(HttpServletRequest r){AuthFilter.role(r,"ADMIN");var m=new LinkedHashMap<String,Object>();m.put("totalUsers",db.scalarLong("SELECT COUNT(*) FROM users"));m.put("activeUsers",db.scalarLong("SELECT COUNT(*) FROM users WHERE enabled=1"));m.put("totalProperties",db.scalarLong("SELECT COUNT(*) FROM properties"));m.put("activeProperties",db.scalarLong("SELECT COUNT(*) FROM properties WHERE status='ACTIVE'"));m.put("pendingProperties",db.scalarLong("SELECT COUNT(*) FROM properties WHERE status='PENDING_APPROVAL'"));m.put("appointments",db.scalarLong("SELECT COUNT(*) FROM appointments"));m.put("openInquiries",db.scalarLong("SELECT COUNT(*) FROM inquiries WHERE status IN ('NEW','IN_PROGRESS')"));m.put("openComplaints",db.scalarLong("SELECT COUNT(*) FROM complaints WHERE status IN ('NEW','IN_PROGRESS')"));m.put("usersByRole",db.all("SELECT role,COUNT(*) count FROM users GROUP BY role"));m.put("propertiesByStatus",db.all("SELECT status,COUNT(*) count FROM properties GROUP BY status"));return Api.ok("Admin metrics retrieved.",m);}@GetMapping("/audit-logs")public Map<String,Object>logs(HttpServletRequest r){AuthFilter.role(r,"ADMIN");var x=db.all("SELECT a.*,u.full_name actor_name,u.email actor_email FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 250");List<Map<String,Object>>out=new ArrayList<>();for(var a:x){var m=new LinkedHashMap<String,Object>();for(String k:List.of("id","actor_id","actor_name","actor_email","action","entity_type","entity_id","details"))m.put(camel(k),Rows.s(a,k));m.put("createdAt",Rows.l(a,"created_at"));out.add(m);}return Api.ok("Audit logs retrieved.",out);}private String camel(String s){String[]p=s.split("_");StringBuilder z=new StringBuilder(p[0]);for(int i=1;i<p.length;i++)z.append(Character.toUpperCase(p[i].charAt(0))).append(p[i].substring(1));return z.toString();}}
